function build(data){
  var L=[];
  L.push('# '+ (data.name||''));
  if(data.title) L.push('**'+data.title+'**');
  var contact=[]; if(data.email) contact.push('✉ '+data.email); if(data.phone) contact.push('☎ '+data.phone); if(data.location) contact.push('📍 '+data.location);
  if(contact.length) L.push(contact.join('  |  '));
  if(data.summary){ L.push(''); L.push('## 简介'); L.push(data.summary); }
  if(data.skills && data.skills.length){ L.push(''); L.push('## 技能'); L.push(data.skills.map(function(s){return '- '+s;}).join('\n')); }
  if(data.experience && data.experience.length){ L.push(''); L.push('## 经历'); data.experience.forEach(function(e){ L.push('- **'+e.role+'** @ '+e.org+'（'+(e.period||'')+'）'+(e.detail?(' — '+e.detail):'')); }); }
  if(data.education && data.education.length){ L.push(''); L.push('## 教育'); data.education.forEach(function(e){ L.push('- '+e.degree+' @ '+e.school+'（'+(e.year||'')+'）'); }); }
  return L.join('\n');
}
var EXPORTS={build:build};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ResumeForgePure = EXPORTS; }
